import {escapeHTML as h} from './html.js';
const degree=p=>p.routes.some(r=>['college','graduate'].includes(r.key)),keep=(p,e)=>e==='all'||p.routes.some(r=>e==='degree'?['college','graduate'].includes(r.key):r.key===e),names=rs=>rs.map(r=>h(r.title)).join(' · ')||'None';
export function followup052Table(rows,labels,education='all'){
 const paired=rows.filter(r=>r.followup052);if(!paired.length)return '<p>No public follow-up records in this selection. Owner-only cases are outside this experiment.</p>';
 const groups=[['Selection total',paired],...Object.entries(labels).map(([k,label])=>[label,paired.filter(r=>r.phase===k)]).filter(([,rs])=>rs.length)];
 const pair=(rs,p)=>rs.filter(r=>p(r.followup052.before.filter(x=>keep(x,education)))).length+' → '+rs.filter(r=>p(r.followup052.after.filter(x=>keep(x,education)))).length;
 return '<p>Before answers · 0.51 → after one follow-up round · 0.52. Questions were frozen first; independent authors used biographies and anonymous questions without seeing matching outcomes. Positive answers require direct interest evidence. Cohort/search filters select models; education filters select offers while retaining models with no offer in that education group.</p><div class="table-scroll" tabindex="0"><table><thead><tr><th>Cohort</th><th>Models</th><th>Any Top</th><th>College / graduate Top</th><th>Any Top covers lifestyle</th><th>First shown Top covers</th><th>New responses</th><th>Top changed</th></tr></thead><tbody>'+groups.map(([label,rs])=>'<tr><th>'+h(label)+'</th><td>'+rs.length+'</td><td>'+pair(rs,t=>t.length>0)+'</td><td>'+pair(rs,t=>t.some(degree))+'</td><td>'+pair(rs,t=>t.some(p=>p.sustains===true))+'</td><td>'+pair(rs,t=>t[0]?.sustains===true)+'</td><td>'+rs.reduce((n,r)=>n+r.followup052.answers.filter(a=>a.applied&&keep(a,education)).length,0)+'</td><td>'+rs.filter(r=>JSON.stringify(r.followup052.before.filter(p=>keep(p,education)).map(p=>p.id))!==JSON.stringify(r.followup052.after.filter(p=>keep(p,education)).map(p=>p.id))).length+'</td></tr>').join('')+'</tbody></table></div><p>Original holdout and fresh 0.49 holdout remain separate; diagnostic variants enter only when selected. Previously uncertain or declined answers were not rewritten. One round may leave incomplete checks or uncertain defining interests. Higher income never supplies missing interest evidence.</p>';
}
export function followup052Trail(m,education='all'){
 const r=m.followup052;if(!r)return '';
 const answers=r.answers.filter(a=>keep(a,education)),outcomes=r.careerOutcomes.filter(p=>keep(p,education));
 return '<section class="coverage-release"><h3>New follow-up answers · 0.51 → 0.52</h3><p><strong>Before answers:</strong> '+names(r.before.filter(p=>keep(p,education)))+'</p><p><strong>After this round:</strong> '+names(r.after.filter(p=>keep(p,education)))+'</p><p>Added: '+names(r.added.filter(p=>keep(p,education)))+'. Left Top: '+names(r.removed.filter(p=>keep(p,education)))+'.</p><p>'+h(r.reason)+'</p><p>'+r.applied+' responses applied · '+r.positive+' positive reflections · '+r.unknown+' unsure/unfamiliar · '+r.declined+' declined · '+r.skipped+' skipped. Counts describe the full round across education routes.</p>'+(r.inheritedFrom?'<p>Diagnostic variant: exact matching question responses reused from '+h(r.inheritedFrom)+'. This is not independent evidence.</p>':'')+'<p><a href="../student-view.html?case='+encodeURIComponent(m.id)+'&amp;replay=final#/journey/discover">Explore this model after the follow-up round →</a></p><details><summary>Every new answer, confidence and profile evidence · '+answers.length+'</summary>'+answers.map(a=>'<article class="replay-answer"><h4>'+h(a.prompt||a.questionId)+'</h4><p><strong>'+h(a.response||'unasked')+(a.selectedTexts?.length?' · '+h(a.selectedTexts.join(' · ')):'')+'</strong> · '+h(a.confidence||'no inference')+' confidence</p><p>'+h(a.evidence||a.reason||'No authored response.')+'</p><p class="small">'+h((a.biographyPaths||[]).join(' · '))+'</p>'+(a.authoredAnswer?'<p><strong>Original authored response:</strong> '+h(a.authoredAnswer.response)+' · '+h(a.authoredAnswer.confidence)+' confidence. '+h(a.authoredAnswer.evidence)+'</p>':'')+((a.reviewHold||a.reviewReason)?'<p><strong>Evidence review:</strong> '+h(a.reviewHold||a.reviewReason)+'</p>':'')+(a.reviewFollowup?'<p><strong>Question to resolve this:</strong> '+h(a.reviewFollowup)+'</p>':'')+'<p>'+h(a.applied?'Applied as profile-inferred evidence':'Not applied: '+a.reason)+'</p></article>').join('')+'</details><details><summary>Profession outcomes and remaining questions · '+outcomes.length+'</summary>'+outcomes.map(o=>'<article><h4>'+h(o.title)+' · '+h(o.status)+'</h4><p>Check '+(o.checkComplete?'complete':'incomplete')+' · defining interests '+(o.definingConfirmed?'supported':'still unresolved')+'</p>'+o.questions.filter(q=>q.response!=='yes'||q.reviewHold||q.confidence==='low').map(q=>'<p><strong>'+h(q.prompt)+'</strong><br>'+h(q.response)+' · '+h(q.evidence)+'</p>').join('')+'</article>').join('')+'</details></section>';
}
